ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    "status": "400",
    "code": "BILLING_HISTORY:INVALID_PARAMS",
    "message": "connectionNumber, billingAccount and (customerTypeId - customerId) combination cant be empty at the same time.",
    "messageServer": error.description,
    "cause": [
        {
            "origin": "customer-papi-services-v2",
            "message": "connectionNumber, billingAccount and (customerTypeId - customerId) combination cant be empty at the same time."
        }
    ]
}

%dw 2.0
output application/json skipNullOn = "everywhere"
var zsmartResponse = payload.result.result
---
{
	"codeResponse": "200",
	"messageResponse": "OK",
	"accounts": [{
		"transactionID": zsmartResponse.transactionID,
		"accountNumber": vars.billingAccount,
		"invoices": zsmartResponse.billExParamList map ((item, index) -> {
			"billId": item.billID,
			"billType": item.billType,
			"invoiceNumber": item.billNumber,
			"accountId": item.accountNumber default item.acctId,
			"cycleBeginDate": item.cycleBeginDate,
			"cycleEndDate": item.cycleEndDate,
			"invoiceDate": item.entryDate,
			"dueDate": item.dueDate,
			"amount": {
				"value": item.due,
				"formatted": item.formatDue
			},
			"openAmount": {
				"value": item.openAmount,
				"formatted": item.formatOpenAmount
			},
			"paidAmount": {
				"value": item.paidCharge,
				"formatted": item.formatPaidCharge
			},
			"prebalance": {
				"value": item.preBalance,
				"formatted": item.formatPreBalance
			},
			"afterBalance": {
				"value": item.afterBalance,
				"formatted": item.formatAfterBalance
			},
			"wsCharge": {
				"value": item.wrCharge,
				"formatted": item.formatWrCharge
			},
			"settleCharge": {
				"value": item.settleCharge,
				"formatted": item.formatSettleCharge
			},
			"recvCharge": {
				"value": item.recvCharge,
				"formatted": item.formatRecvCharge
			},
			"adjustCharge": {
				"value": item.adjustCharge,
				"formatted": item.formatAdjustCharge
			},
			"status": if ( item.openAmount == "0" ) "Pagada"
          else
            "Pendiente",
			"currencyCode": item.currencyCode,
			"downloadUrl": item.downloadUrl
		})
	}]
}

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p('mongo-db-sapi.resources.dynamicQuery.base-path'),
	body: {
		"query": {
			"aggregate": "MDM_CUENTA_FACTURACION",
			"pipeline": [{
				"\$match": {
					"Tipo_Documento": vars.billingParams.customerIdType,
					"Numero_Identificacion": vars.billingParams.customerId
				}
			}],
			"cursor": {
			}
		}
	},
	headers: vars.billingHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java
var zsmartResponse = {
	"status": "success",
	"transactionID": payload.result.result.transactionID,
	"accountNumber": vars.billingAccount,
	"invoices": payload.result.result.billExParamList map ((item, index) -> {
		"billId": item.billID,
		"billType": item.billType,
		"invoiceNumber": item.billNumber,
		"accountId": item.accountNumber default item.acctId,
		"cycleBeginDate": item.cycleBeginDate,
		"cycleEndDate": item.cycleEndDate,
		"invoiceDate": item.entryDate,
		"dueDate": item.dueDate,
		"amount": {
			"value": item.due,
			"formatted": item.formatDue
		},
		"openAmount": {
			"value": item.openAmount,
			"formatted": item.formatOpenAmount
		},
		"paidAmount": {
			"value": item.paidCharge,
			"formatted": item.formatPaidCharge
		},
		"prebalance": {
			"value": item.preBalance,
			"formatted": item.formatPreBalance
		},
		"afterBalance": {
			"value": item.afterBalance,
			"formatted": item.formatAfterBalance
		},
		"wsCharge": {
			"value": item.wrCharge,
			"formatted": item.formatWrCharge
		},
		"settleCharge": {
			"value": item.settleCharge,
			"formatted": item.formatSettleCharge
		},
		"recvCharge": {
			"value": item.recvCharge,
			"formatted": item.formatRecvCharge
		},
		"adjustCharge": {
			"value": item.adjustCharge,
			"formatted": item.formatAdjustCharge
		},
		"status": if ( item.openAmount == "0" ) "Pagada"
          else
            "Pendiente",
		"currencyCode": item.currencyCode,
		"downloadUrl": item.downloadUrl
	})
}
---
vars.billingHistoryAcc + zsmartResponse
